// ratelimit.go
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be constructed via NewLimiter; the zero value is not usable.
type Limiter struct {
	mu        sync.Mutex
	rate      float64 // tokens per second
	burst     float64 // bucket capacity
	tokens    float64
	last      time.Time
	clock     Clock
	nowFn     func() time.Time // fast path when clock is realClock
}

// NewLimiter creates a Limiter refilling at rate tokens per second with
// capacity burst. rate must be > 0 and burst must be >= 1.
func NewLimiter(rate float64, burst int) (*Limiter, error) {
	return NewLimiterWithClock(rate, burst, realClock{})
}

// NewLimiterWithClock is NewLimiter with an injectable clock.
func NewLimiterWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	if rate <= 0 {
		return nil, fmt.Errorf("ratelimit: rate must be > 0, got %v", rate)
	}
	if burst < 1 {
		return nil, fmt.Errorf("ratelimit: burst must be >= 1, got %d", burst)
	}
	now := clock.Now()
	l := &Limiter{
		rate:  rate,
		burst: float64(burst),
		// Start full so a fresh limiter permits an initial burst.
		tokens: float64(burst),
		last:   now,
		clock:  clock,
	}
	if _, ok := clock.(realClock); ok {
		l.nowFn = time.Now
	}
	return l, nil
}

// advance refills tokens based on elapsed time since last refill.
// Caller must hold l.mu.
func (l *Limiter) advance(now time.Time) {
	if now.Before(l.last) {
		// Clock went backwards; do not grant tokens.
		l.last = now
		return
	}
	elapsed := now.Sub(l.last)
	if elapsed <= 0 {
		return
	}
	l.tokens += elapsed.Seconds() * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
	l.last = now
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(time.Time{}, 1) }

// AllowN reports whether n tokens are available at time now.
// If now is the zero time, the limiter's clock supplies the current time.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	if now.IsZero() {
		if l.nowFn != nil {
			now = l.nowFn()
		} else {
			now = l.clock.Now()
		}
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for diagnostics).
func (l *Limiter) Tokens() float64 {
	if l.nowFn != nil {
		return l.snapshot(l.nowFn())
	}
	return l.snapshot(l.clock.Now())
}

func (l *Limiter) snapshot(now time.Time) float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	return l.tokens
}
