func TestAllowNConcurrent(t *testing.T) {
	const burst = 100
	l, _ := NewLimiter(burst, burst)
	var mu sync.Mutex
	allowed := 0
	var wg sync.WaitGroup
	for i := 0; i < burst * 2; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.Allow() {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != burst {
		t.Fatalf("allowed = %d, want %d", allowed, burst)
	}
}

